import { CustomPageStore } from '@/components/CustomPage';
import app from '@/store/app';
import ajax from '@/utils/ajax';
import globals from "@/environments/hoc";
import { Message } from '@arco-design/web-react';
import { action, observable, makeObservable } from 'mobx';
import React from 'react';
import { moduleStore } from 'react-converter-code';


class Store {

    database: any = null;
    page: CustomPageStore;

    constructor(id){
        makeObservable(this);
        this.init(id);
    }

    @observable key = Date.now();
    @action
    updateKey = () => {
        this.key = Date.now();
    }


    @observable lodaing = false;
    @action
    setLoading = (bool: boolean) => {
        this.lodaing = bool;
    }
    

    @observable data: any = {};
    @action
    setData = async (data) => {
        const { extraInfo } = data;
        if(extraInfo.components){
            await moduleStore.syncModuleIds(extraInfo.components);
            for (const key of extraInfo.components) {
                console.log('key', key)
                const element = moduleStore.elements.get(key);
                globals.state[key] = element.render;
            }
        }
        this.data = data;
    }
    

    /**
     * 加载所有模块
     */
    createPage = () => {
        const { id, content } = this.data;
        if(!id) return;
        this.page = new CustomPageStore({ uid:id });
        this.page.setData(content);
        return this.page;
    }

    
    /**
     * 初始化
     */
    init = (pageId: string) => {
        ajax.post('/apijson/get', {
            "Page": {
                id: pageId,
                // appId: app.appId,
            }
        }).then(async (res) => {
            if (res.Page) {
                const { content, extraInfo } = res.Page;
                const info = JSON.parse(extraInfo || "{}");
                return this.setData({
                    ...res.Page,
                    content: JSON.parse(content || "{}"),
                    extraInfo: info,
                })
            } else {
                Message.error('当前页面不存在');
            }
        })
    }


    /**
     * 保存页面
     */
    savePage = async () => {
        const { database } = this;
        if(database.state.length){
            const list = database.state.filter((page) => {
                // 页面解析时，需要优先把页面去掉
                return page.isComponent && page.parse.isSave
            }).slice().reverse();
            for (const page of list) {
                const data = page.getData();
                const resProps = {
                    props: data.page.props,
                    content: data,
                    jsxRender: await page.getRenderText(),
                }
                const element = moduleStore.elements.get(page.uid);
                await ajax.post('/apijson/put', {
                    Module: {
                        id: page.uid,
                        ...resProps,
                        content: JSON.stringify(data),
                    }
                }).then(() => {
                    moduleStore.updateElement(page.uid, {
                        ...element,
                        ...resProps
                    })
                })
            }
        }
        if(this.page.parse){
            const data = this.page.getData();
            const jsxRender = await this.page.getRenderText();
            return ajax.post('/apijson/put', {
                Page: {
                    id: this.page.uid,
                    content: JSON.stringify(data),
                    jsxRender,
                }
            }).then(() => {
                Message.success('页面保存成功');
                // history.goBack();
                return this.setData({
                    ...this.data,
                    content: data,
                    jsxRender,
                })
            })
        }
    }
}

export default Store;