import React, { useMemo, useRef, useState } from 'react';
import Store from './store';
import { useObserver } from 'mobx-react-lite';
import { dynamicCreateModule } from '@/environments/hoc'
import { Button, PageHeader, Space, Message, Modal, Spin, Card } from '@arco-design/web-react';
import { IconEdit, IconRecordStop } from '@arco-design/web-react/icon';
import styles from './index.module.less';

interface PageContentProps {
    pageId: string;
}
const PageContent = ({ pageId }: PageContentProps) => {

    const [store] = useState(() => new Store(pageId))
    const ref = useRef();
    const [page, setPage] = useState<any>();

    
    return useObserver(() => {

        const Element: any = useMemo(() => {
            const { jsxRender } = store.data;
            
            return jsxRender? dynamicCreateModule(jsxRender) : () => null
        },[store.data])

        return (
            <React.Fragment>
                <div ref={ref} className={styles.pageContent}>
                    <Element key={store.key} />
                    <Button
                        type="primary" shape="round"
                        icon={Boolean(page)? <IconRecordStop /> : <IconEdit />}
                        className={styles.pointer}
                        onClick={() => {
                            console.log('parse', store.database, ref.current)
                            if(page){
                                Modal.confirm({
                                    title: "保存提示",
                                    content: "保存提示，是否保存当前更改信息",
                                    onCancel: () => {
                                        store.updateKey();
                                        setPage(null);
                                    },
                                    onOk: () => {
                                        store.setLoading(true);
                                        return store.savePage().then((res) => {
                                            store.updateKey();
                                            setPage(null);
                                        }).finally(() => {
                                            store.setLoading(false);
                                        })
                                    }
                                })
                            }else {
                                const pageStore = store.createPage();
                                if(pageStore){
                                    Message.info("动态页面编辑已开启，再次点击可关闭动态信息编辑")
                                    const database = pageStore.parse.initPage(
                                        ref.current,
                                        {
                                            update: () => null
                                        }
                                    )
                                    store.database = database;
                                    setPage(pageStore);
                                }
                            }
                        }}
                    />
                </div>
            </React.Fragment>
        )
    })
}

export default PageContent;